"use client";

import {Label, Slider} from "@heroui/react";

export function Range() {
  return (
    <Slider
      className="w-full max-w-xs"
      defaultValue={[100, 500]}
      formatOptions={{currency: "USD", style: "currency"}}
      maxValue={1000}
      minValue={0}
      step={50}
    >
      <Label>Price Range</Label>
      <Slider.Output />
      <Slider.Track>
        {({state}) => (
          <>
            <Slider.Fill />
            {state.values.map((_, i) => (
              <Slider.Thumb key={i} index={i} />
            ))}
          </>
        )}
      </Slider.Track>
    </Slider>
  );
}

"use client";

import {Label, Slider} from "@heroui/react";

export function RenderFunction() {
  return (
    <Slider
      className="w-full max-w-xs"
      defaultValue={30}
      render={(props) => <div {...props} data-custom="foo" />}
    >
      <Label>Volume</Label>
      <Slider.Output />
      <Slider.Track>
        <Slider.Fill />
        <Slider.Thumb />
      </Slider.Track>
    </Slider>
  );
}

import {Label, Slider} from "@heroui/react";

export function CustomStyles() {
  return (
    <Slider className="w-full max-w-xs" defaultValue={40}>
      <Label className="font-medium text-foreground">Brightness</Label>
      <Slider.Output className="text-xs text-muted tabular-nums" />
      <Slider.Track className="bg-default">
        <Slider.Fill className="bg-accent" />
        <Slider.Thumb className="bg-accent after:bg-accent-foreground" />
      </Slider.Track>
    </Slider>
  );
}
